mapper.select:
SELECT t2.test_name, t2.start_time, t1.sum_score, t3.subject_name, t2.question_num, t1.`status`, t2.deadline, t2.suggest_duration, t1.test_answer_id FROM ms_test_answer AS t1 JOIN ms_test AS t2 ON t1.test_id = t2.test_id AND t2.test_type != 4 JOIN ms_subjects AS t3 ON t2.subject_id = t3.subject_id
t1.user_id = #{t.userId} AND t1.del_flag = 0
AND t3.subject_id=#{t.subjectId}
AND t2.test_type=#{t.testType}

SELECT t1.test_answer_id, t1.`status`, t2.test_name, t3.subject_name, t4.video_url, t4.cover_url, t4.video_id, t4.video_name FROM ms_test_answer AS t1 JOIN ms_test AS t2 ON t1.test_id = t2.test_id AND t2.test_type = 4 LEFT JOIN ms_subjects AS t3 ON t3.subject_id = t2.subject_id LEFT JOIN ms_video AS t4 ON t4.test_id = t1.test_id
t1.`status` = 2 AND t1.user_id = #{v.userId} AND t1.del_flag = 0
AND t3.subject_id=#{v.subjectId}

SELECT t1.test_id, t1.test_name, t2.grade, t2.subject_name, t1.create_time FROM ms_test t1 INNER JOIN ms_subjects t2 ON t1.subject_id = t2.subject_id
t1.test_id = #{testId}
t2.grade = #{grade}
t2.subject_id = #{subjectId}

SELECT COUNT(*)
FROM ms_test_answer
WHERE test_id = #{testId}

select t.test_id, s.subject_name, s.grade, t.test_name, c.class_name, t.create_time from ms_test t left join ms_subjects s on t.subject_id=s.subject_id left join ms_test_class tc on t.test_id = tc.test_id left join ms_class c on tc.class_id = c.class_id where t.del_flag='0' and s.grade=#{grade}
and t.test_id=#{query.testId}
and s.subject_id=#{query.subjectId}
